'use client';
/**
 * OAppProviders — 一站式 Provider 栈包装。
 *
 * 把 helios-blocks 的 ThemeProvider + LangProvider 包好,简化项目接入。
 * 后续可加 Toast / Persistence / Auth(项目按需启用 prop)。
 *
 * 用法:
 *   OAppProviders theme="professional"             默认中英并列 + 主题
 *   OAppProviders theme="mneme-friendly" mode="system" lang="zh"
 *
 * 想自定义层级的项目可不用本组件,直接拼 ThemeProvider / LangProvider。
 */
import type { ReactNode } from 'react';
import { ThemeProvider, LangProvider, type UiLang } from '@helios/blocks';

export interface OAppProvidersProps {
  children: ReactNode;
  /** 主题名(如 'professional' / 'terminal-dark' / 'mneme-friendly')。 */
  theme?: string;
  /** 颜色模式。'system' 跟随操作系统明暗(blocks 大于等于 2.11)。 */
  mode?: 'light' | 'dark' | 'system';
  /** UI 密度。 */
  density?: 'compact' | 'comfortable' | 'terminal';
  /** 界面语言。默认 'zh-en'(中英并列);'zh' 纯中文;'en' 纯英文。 */
  lang?: UiLang;
}

export function OAppProviders({
  children,
  theme = 'professional',
  mode,
  density,
  lang = 'zh-en',
}: OAppProvidersProps) {
  const themeProps: Record<string, unknown> = { theme };
  if (mode !== undefined) themeProps.mode = mode;
  if (density !== undefined) themeProps.density = density;
  return (
    <ThemeProvider {...themeProps}>
      <LangProvider lang={lang}>
        {children}
      </LangProvider>
    </ThemeProvider>
  );
}
